with flattened as (select id, plan, currency, element from price_tiers lateral view explode(tier_limits) li as element) select id, plan, currency, element, rank() over (partition by currency order by element desc nulls last) as element_rank, rank() over (partition by plan, currency order by element desc nulls first) as element_rank_2, avg(element) over (partition by currency) as currency_avg_element from flattened;
